import{_ as t,o as a,c as r,a5 as s}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"3.4.10 List Workspace","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-10-list-workspace/spec.md","filePath":"feature/agency-workspace/3-4-10-list-workspace/spec.md"}'),o={name:"feature/agency-workspace/3-4-10-list-workspace/spec.md"};function i(n,e,c,l,d,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="_3-4-10-list-workspace" tabindex="-1">3.4.10 List Workspace <a class="header-anchor" href="#_3-4-10-list-workspace" aria-label="Permalink to &quot;3.4.10 List Workspace&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.4.10</td></tr><tr><td>Feature</td><td>List Workspace</td></tr><tr><td>Domain</td><td>Agency &amp; Workspace (FR 3.4)</td></tr><tr><td>Role</td><td>MANAGER / CREATOR / CLIENT</td></tr><tr><td>Version</td><td>2.2 — 2026-09-23 — rewritten to the standard FR format</td></tr><tr><td>Document status</td><td>Implemented</td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when a signed-in user opens the Workspace list screen.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Any Workspace member (MANAGER, CREATOR, or CLIENT).</li><li><strong>Purpose:</strong> Shows every Workspace the current user belongs to, so the user can pick one to work in.</li><li><strong>Interface:</strong> Workspace list screen of the current user — a list of Workspace entries, not scoped under an Agency route.</li><li><strong>Data Processing:</strong> The system reads the current user&#39;s active Workspace memberships, loads the Workspace records those memberships point to, and maps each one to a Workspace summary.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Workspace List Screen (<code>WorkspacePage</code>, <code>WorkspaceCardGrid</code>):</p><ul><li>A single grid screen titled with the user&#39;s Workspaces (<code>workspace.list.title</code>).</li><li>Each card shows an initials badge, the Workspace name, and its slug; clicking a card navigates to <code>/workspaces/:id/settings</code>.</li><li>An empty state message is shown when the user belongs to no Workspace.</li><li>A &quot;Create Workspace&quot; button navigates to the create form (FR 3.4.12).</li><li>⚠ BA conflict (needs team decision): <code>workspaceService.listManagedWorkspaces()</code> (<code>GET /api/v1/workspaces/my-managed</code>, returning id/name/slug/logoUrl/role/memberCount) exists in the frontend service layer, but the current <code>WorkspacePage</code> (<code>index.tsx</code>) does not call it or render a &quot;Workspaces I manage&quot; view anywhere. Either that view was removed/not yet wired up, or it lives on a screen not reviewed here — needs confirmation before documenting it as shipped UI.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> The caller&#39;s authenticated identity (taken from the session principal).</li><li><strong>Input optional:</strong> None.</li><li><strong>System data:</strong> Active Workspace membership rows of the current user; the Workspace records those memberships reference.</li><li><strong>Output:</strong> The Workspaces the user belongs to — id, name, agencyId, slug, ownerId, settings (including reportFrequency), industry, companySize, website, phone, location, description, brandColor, logoIcon, logoUrl, tagline, foundedYear, facebookUrl, linkedinUrl, instagramUrl, isActive, createdAt. The frontend list card only renders the name and slug. A separate &quot;managed&quot; endpoint (<code>GET /api/v1/workspaces/my-managed</code>) returns id, name, slug, logoUrl, role, and memberCount per Workspace, but see the BA conflict note in Screen Layout on whether it is currently surfaced in the UI.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-29:</strong> Multi-tenancy — every workspace-scoped resource carries workspaceId; a user with no active membership cannot read/write the workspace regardless of system role (except ADMIN). Applied here as: a Workspace is returned when either (a) the current user has an active membership row in it (MemberRole MANAGER, CREATOR, or CLIENT), or (b) the current user is the Owner of the Agency that Workspace belongs to — per <code>docs/ba/10-roles-permissions-matrix.md</code> Tầng 1, an Agency Owner sees every Workspace of their Agency, not only ones they are a member of. <ul><li><strong>Fixed 2026-09-24:</strong> an earlier version of this spec/code scoped the listing to membership only, so an Agency Owner did not automatically see every Workspace of their own Agency — this was a real gap against BA, now corrected in <code>WorkspaceServiceImpl.listMyWorkspaces</code>.</li></ul></li><li><strong>BR-03:</strong> The listing is read-only; there is no business error code for it. The only failure is a missing session, rejected with 401 through the shared authentication mechanism.</li><li><strong>Known gap:</strong> <code>listMyWorkspaces</code> does not currently exclude SOFT_DELETED workspaces from the list — the merge of owned-Agency workspace IDs and membership workspace IDs is passed straight into <code>workspaceRepository.findAllById(workspaceIds)</code> with no status filter in the repository query or the stream. A soft-deleted Workspace (see FR 3.4.15 Delete Workspace) may still appear in this list until this is fixed. Docs-only note; not fixed here.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>The caller must be signed in; otherwise the request is rejected with 401.</li><li>A user with no Workspace membership must receive an empty list, not an error.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>User opens the Workspace list screen.</li><li>System reads the current user&#39;s active Workspace memberships.</li><li>System loads the Workspace records referenced by those memberships.</li><li>System maps each Workspace to a Workspace summary.</li><li>Screen shows the Workspaces the user belongs to; an empty list is shown when the user belongs to none.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>5.a1: User belongs to no Workspace (BR-29) → an empty list is returned, HTTP 200. 5.a2: The empty state is displayed on the screen.</li><li>5.b1: User is not signed in → 401 through the shared authentication mechanism. 5.b2: The user is redirected to sign in.</li><li>5.c1: A Workspace referenced by an owned Agency or an active membership has actually been soft-deleted (known gap above) → it is still returned and displayed as if active. 5.c2: No workaround on the client side; tracked as a backend fix.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>No data is changed; the Workspaces the user belongs to are displayed.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>None.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p><a href="./../../../BA/01-organization-structure.html">01-organization-structure.md</a>, <a href="./../../../BA/03-agency-workspace-management.html">03-agency-workspace-management.md</a></p>',27)])])}const m=t(o,[["render",i]]);export{p as __pageData,m as default};
